-- SHA256 f818db120d7d7653cec0bfc10e30bd78834680a6fff411ebf20f68d7945ee262
-- ============================================================================
-- =============================================================================
-- NON-DESTRUCTIVE LEGACY MEDIA COMPATIBILITY
-- =============================================================================
--
-- Historical note:
-- An earlier draft of this migration removed a legacy URL from posts.media_urls
-- and deleted the matching post_media row after one playback failure. That is
-- unsafe: a 403/404 public URL can also mean the bucket policy changed, a signed
-- URL expired, CDN/DNS is temporarily unavailable, or another historical media
-- source must be tried.
--
-- `posts.media_urls` and `post_media` are user data. They must never be deleted
-- merely because one client-side URL failed to load.
--
-- Recovery is now intentionally runtime/backward-compatible:
--   * structured and legacy media are merged by logical position;
--   * every historical URL is kept as an ordered fallback candidate;
--   * current-project legacy Supabase bucket/key references may be re-signed;
--   * playback tries all candidates before showing a retry state;
--   * no post/media metadata is removed or downgraded.
--
-- This migration is therefore a data-preserving marker only. Keeping the
-- filename lets production migration history advance without executing the old
-- destructive statements.
-- =============================================================================

do $$
begin
  raise notice 'Legacy media repair is runtime-based and non-destructive; no post/media rows were changed.';
end
$$;

notify pgrst, 'reload schema';


-- ============================================================================
-- SOURCE B-web: 20260906010535_legacy_post_storage_read_access.sql
-- SHA256 972312b18cbb1ba72261fdbad17a08c1b51d4eb165d9c48e319333075276f3a9
-- ============================================================================
-- Legacy posts and private chat attachments share these buckets. Keep the
-- buckets private and allow signing only objects attached to a visible,
-- published post by that object's author. No post, media, or object is changed.
-- The absolute URL prefix is deliberately scoped to this production project.

drop policy if exists "Legacy media readable by post audience" on storage.objects;
create policy "Legacy media readable by post audience"
  on storage.objects
  for select
  to anon, authenticated
  using (
    bucket_id in ('message-attachments', 'chat-media')
    and exists (
      select 1
      from public.posts p
      cross join lateral (
        select array[
          'storage://' || objects.bucket_id || '/' || objects.name,
          'https://mbhjganbihamoiqmankv.supabase.co/storage/v1/object/public/' || objects.bucket_id || '/' || objects.name,
          'https://mbhjganbihamoiqmankv.supabase.co/storage/v1/object/sign/' || objects.bucket_id || '/' || objects.name,
          'https://mbhjganbihamoiqmankv.supabase.co/storage/v1/object/authenticated/' || objects.bucket_id || '/' || objects.name
        ]::text[] as urls
      ) refs
      where p.user_id::text = (storage.foldername(objects.name))[1]
        and coalesce(p.status, 'published') = 'published'
        -- The posts and post_media SELECT policies still apply in this query.
        and (
          exists (
            select 1
            from unnest(p.media_urls) as legacy(url)
            where split_part(split_part(legacy.url, '?', 1), '#', 1) = any(refs.urls)
          )
          or exists (
            select 1
            from public.post_media pm
            where pm.post_id = p.id
              and (
                (pm.storage_bucket = objects.bucket_id and pm.storage_key = objects.name)
                or (pm.thumbnail_bucket = objects.bucket_id and pm.thumbnail_key = objects.name)
                or split_part(split_part(pm.storage_url, '?', 1), '#', 1) = any(refs.urls)
                or split_part(split_part(pm.thumbnail_url, '?', 1), '#', 1) = any(refs.urls)
              )
          )
        )
    )
  );

notify pgrst, 'reload schema';


